window.RP_SESSION={"id":"S-d24774d3bf08","messages":[{"id":"RP-0159483","time":"2026-05-18T23:27:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어쩌면 뒷골목은 길드원들에게 조금은 힘든 곳일지도 모른다고 미샤는 생각했다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159484","time":"2026-05-18T23:28:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"델타인도 그렇고 라르손도 그렇고 뒷골목에 간간히 들린 적은 있었다고 들었는데...","characters":["P-41ba4c5736e6"]},{"id":"RP-0159485","time":"2026-05-18T23:29:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"길가던 건달에게 잡혀서 탈탈 털리고 라르손은 똥범벅이 된 바지를 입고서 복귀한 모습을 보고서 미샤는 의뢰를 취소하고 직접 나서야하나 잠시 고민했다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159486","time":"2026-05-18T23:29:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"하지만 누구나 실패는 하는 법이다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159487","time":"2026-05-18T23:30:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"누가 죽은 것도 아니고 물론 있던 무기들은 죄다 털린 것 같지만.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159488","time":"2026-05-18T23:31:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"모두 의욕이 꺾인 것도 아니고. 재정비 후에 다시 찾아간다고 했으니까.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159489","time":"2026-05-18T23:31:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"다만 조금 걸리는 것은 [배달]에 대한 이야기.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159490","time":"2026-05-18T23:32:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어쩌면 조금은 깊게 발을 들일지도 모르겠다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159491","time":"2026-05-18T23:33:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-41ba4c5736e6"]},{"id":"RP-0159492","time":"2026-05-18T23:33:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0159493","time":"2026-05-18T23:33:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 다음에 조금 도움을 줘야하나 고민하고 있었다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159494","time":"2026-05-18T23:33:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"막상 그러자니 길드에 의뢰를 준 취지가 빗겨나가는 것 같다는 생각도 든다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159495","time":"2026-05-18T23:41:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"타닥 타닥\n\n모닥불이 계속 타오른다. 은은한 적색 불길이 따스하게 미샤를 비춘다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159496","time":"2026-05-18T23:42:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어느샌가 모닥불을 슬쩍 길드에서 피우는 것도 습관이 되어버렸다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159497","time":"2026-05-18T23:42:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"생각해보면 요즘 좀 조용한 것 같기는 하네요.\"","characters":["P-41ba4c5736e6"]},{"id":"RP-0159498","time":"2026-05-18T23:42:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"처음 미샤가 길드에 왔을 때.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159499","time":"2026-05-18T23:47:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"스텔라가 힘써준 덕인가? 사고뭉치들이 조금 조용해진 것 같다.\n\n항상 맥주나 들고 다니던 아나이스, 사고뭉치 엘타리온, 션도 아직 루체에 대한 소식을 모르다 보니 여성 관계도 제법 복잡했고. 사고뭉치는 아니지만 지금 길드원을 가족처럼 여기던 토르번도 나름 처음에는 어색해하는 느낌도 있었고. 요즘 님드도 말이 제법 늘었다. 그러고보니 아도니스도.\n\n물론 바뀌지 않은 친구들도 있다. \n\n여전히 무슨 생각을 하는지 알기 힘들던 폴라리스. 그러고보니 여행을 갔다고 했던가? 아이다는 여전히 흉흉한 무언가가 붙어있는 것 같고. 머챈트 언니나 머독도 한결 같다. 델타인은 여전히 보면 묘하게 짜증난다. 모나는.. 처음처럼 불안하게 느껴지지는 않는다. 생각보다 똑 부러지는 사람이라는 것을 이제는 안다. \n\n그 외에도 많은 길드원들이 있다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159500","time":"2026-05-18T23:48:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"스카일라와 달리 도란도란 주변 사람들과 잘 지내는 길드를 보면 머독이나 토르번이 이야기한 가족에 가까운 단체라는 것이 조금은 어떤 느낌일지 알 것 같다고 미샤는 생각했다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159501","time":"2026-05-18T23:49:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"모닥불이 거의 다 타올랐다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159502","time":"2026-05-18T23:49:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"옅은 불똥과 슬슬 서늘해지는 봄 밤의 날씨.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159503","time":"2026-05-18T23:49:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"오늘따라 조용하네요.\"","characters":["P-41ba4c5736e6"]},{"id":"RP-0159504","time":"2026-05-18T23:49:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"그 탓에 조금은 감정적이 된 것일지도 모른다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159505","time":"2026-05-18T23:50:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 자리를 슥슥 정리하고서 일어났다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0159506","time":"2026-05-18T23:50:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-41ba4c5736e6"]},{"id":"RP-0159507","time":"2026-05-18T23:50:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
